-- ============================================================================
-- 00092 — Import contrôlé du backup "abonnement excel.xlsx" (ancien logiciel)
--
-- Source : data/abonnement excel.xlsx (1358 lignes d'abonnement, 922 adhérents)
--   - 847 membres matchés à la BDD QLF GYM
--   - 75 membres créés
--   - 1358 abonnements historiques importés (1 ligne = 1 abonnement)
--   - 1029 paiements (lignes avec verser > 0)
-- Généré par outil d'analyse (uuid déterministes, rejouable idempotent).
-- ============================================================================

-- 0. Dissocier le paiement lié à un abonnement seedé (évite FK vers une sub supprimée)
UPDATE payments p
SET subscription_id = NULL
WHERE p.subscription_id IN (
  SELECT s.id FROM member_subscriptions s
  JOIN members m ON m.id = s.member_id
  WHERE m.organization_id = '782738ec-0277-4bbb-aee2-b3ec561b2a07' AND m.notes ILIKE '%%groupage%%'
);

-- 1. Suppression des abonnements synthétiques (00057) des membres seedés.
--    Les vraies subs du backup sont réimportées à l'étape 5.
DELETE FROM member_subscriptions s
USING members m
WHERE s.member_id = m.id
  AND m.organization_id = '782738ec-0277-4bbb-aee2-b3ec561b2a07'
  AND m.notes ILIKE '%%groupage%%';

-- 2. Staging
DROP TABLE IF EXISTS _bak.import_staging;
CREATE TABLE _bak.import_staging (
  line_no INT, legacy_member_id TEXT, legacy_sub_id TEXT, target_member_id UUID,
  action TEXT, sub_id UUID, nomprenom TEXT, datenaissance DATE, sex TEXT, groupage TEXT,
  adresse TEXT, phone TEXT, poids TEXT, taille TEXT, inscription DATE, joue DATE,
  barcode TEXT, typeabonnement TEXT, nbrsceance INT, consomation INT,
  datedebut DATE, datefin DATE, montant NUMERIC, verser NUMERIC,
  reste_mismatch BOOLEAN, is_payed TEXT, notes TEXT
);

