-- 4. Mise à jour des membres existants matchés (847)
UPDATE members m
SET birth_date    = CASE WHEN m.birth_date = '1998-01-01' THEN st.datenaissance ELSE m.birth_date END,
    gender        = CASE WHEN m.gender IS NULL OR m.gender = 'male' THEN st.sex ELSE m.gender END,
    phone         = COALESCE(NULLIF(m.phone, ''), st.phone),
    address       = COALESCE(NULLIF(m.address, ''), NULLIF(st.adresse, '')),
    barcode       = COALESCE(m.barcode, NULLIF(st.barcode, '')),
    last_visit    = COALESCE(m.last_visit, st.joue),
    notes         = CASE WHEN st.notes <> '' THEN st.notes ELSE m.notes END,
    legacy_id     = COALESCE(m.legacy_id, st.legacy_member_id),
    import_source = COALESCE(m.import_source, 'BACKUP_ANCIEN_LOGICIEL')
FROM _bak.import_staging st
WHERE st.target_member_id = m.id
  AND st.action = 'matched';

-- 5. Abonnements historiques (1 ligne fichier = 1 membre_subscription)
WITH type_ids AS (
  SELECT
    (SELECT id FROM subscription_types
      WHERE organization_id = '782738ec-0277-4bbb-aee2-b3ec561b2a07' AND btrim(name) = 'Mensuel' AND price = 2000
        AND max_classes = 12 LIMIT 1) AS mensuel_id,
    (SELECT id FROM subscription_types
      WHERE organization_id = '782738ec-0277-4bbb-aee2-b3ec561b2a07' AND name = 'Par séance' LIMIT 1) AS seance_id
)
INSERT INTO member_subscriptions
  (id, organization_id, member_id, subscription_type_id, start_date, end_date,
   total_amount, amount_paid, status, sessions_total, sessions_used, legacy_id,
   import_source, created_at)
SELECT
  st.sub_id,
  '782738ec-0277-4bbb-aee2-b3ec561b2a07',
  st.target_member_id,
  CASE WHEN st.typeabonnement = 'Mensuel' THEN COALESCE(t.mensuel_id, t.seance_id)
       ELSE t.seance_id END,
  st.datedebut,
  st.datefin,
  COALESCE(st.montant, 0),
  COALESCE(st.verser, 0),
  CASE WHEN st.is_payed = '1' AND st.datefin >= CURRENT_DATE THEN 'active'
       WHEN st.is_payed = '1' THEN 'expired'
       WHEN st.datefin >= CURRENT_DATE THEN 'pending_payment'
       ELSE 'expired' END,
  st.nbrsceance,
  st.consomation,
  st.legacy_sub_id,
  'BACKUP_ANCIEN_LOGICIEL',
  st.datedebut
FROM _bak.import_staging st
CROSS JOIN type_ids t
ON CONFLICT (id) DO NOTHING;

