INSERT INTO payments
  (id, organization_id, member_id, subscription_id, amount, payment_date,
   payment_method, status, notes, import_source)
SELECT
  p.pay_id::uuid,
  '782738ec-0277-4bbb-aee2-b3ec561b2a07',
  st.target_member_id,
  st.sub_id,
  st.verser,
  st.datedebut,
  'cash',
  'completed',
  'line=' || st.line_no || '|legacy_member=' || st.legacy_member_id || '|legacy_sub=' || st.legacy_sub_id,
  'BACKUP_ANCIEN_LOGICIEL'
FROM _bak.import_staging st
JOIN pay_ids p ON p.line_no = st.line_no
WHERE COALESCE(st.verser, 0) > 0;

