INSERT INTO import_mapping (batch_id, line_no, legacy_member_id, legacy_sub_id, db_member_id, db_sub_id, action, match_level, note)
SELECT
  '99e3e9f2-e8bc-58ce-b193-4fb6fba4e83d', st.line_no, st.legacy_member_id, st.legacy_sub_id,
  st.target_member_id, st.sub_id,
